mapper.insert:
insert into team (
    team_id, team_name, leader_id, description, avatar_url, status, member_count, max_member_count, create_time, update_time
) values (
    #{teamId}, #{teamName}, #{leaderId}, #{description}, #{avatarUrl}, #{status}, #{memberCount}, #{maxMemberCount}, #{createTime}, #{updateTime}
)

mapper.select:
select

from team
where leader_id = #{leaderId}
order by create_time desc

    limit #{offset}, #{limit}

select count(1)
from team
where leader_id = #{leaderId}

select count(1)
from team
where leader_id = #{leaderId}
and status = #{status}
